import{_ as a,o as s,c as n,a2 as t}from"./chunks/framework.BS0bAV7E.js";const u=JSON.parse('{"title":"QEMU 调试技巧","description":"","frontmatter":{},"headers":[],"relativePath":"zh/troubleshooting/qemu-debugging.md","filePath":"zh/troubleshooting/qemu-debugging.md"}'),o={name:"zh/troubleshooting/qemu-debugging.md"};function i(l,e,p,d,r,c){return s(),n("div",null,[...e[0]||(e[0]=[t(`<h1 id="qemu-调试技巧" tabindex="-1">QEMU 调试技巧 <a class="header-anchor" href="#qemu-调试技巧" aria-label="Permalink to &quot;QEMU 调试技巧&quot;">​</a></h1><h2 id="捕获全部内容" tabindex="-1">捕获全部内容 <a class="header-anchor" href="#捕获全部内容" aria-label="Permalink to &quot;捕获全部内容&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>qemu-system-x86_64 -m 512 -cdrom build/opencube.iso \\</span></span>
<span class="line"><span>    -serial file:boot.log -display none \\</span></span>
<span class="line"><span>    -netdev user,id=n1 -device e1000,netdev=n1</span></span></code></pre></div><p>串行日志就是启动过程记录 - 每个子系统都会输出一个 <code>OK</code>。</p><h2 id="观察宿主机-而不仅仅是虚拟机" tabindex="-1">观察宿主机，而不仅仅是虚拟机 <a class="header-anchor" href="#观察宿主机-而不仅仅是虚拟机" aria-label="Permalink to &quot;观察宿主机，而不仅仅是虚拟机&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>-d int,cpu_reset,guest_errors -D qemu.log    (interrupts/resets/errors)</span></span>
<span class="line"><span>-monitor stdio                               (QEMU monitor alongside)</span></span></code></pre></div><h2 id="使用-gdb-调试内核" tabindex="-1">使用 GDB 调试内核 <a class="header-anchor" href="#使用-gdb-调试内核" aria-label="Permalink to &quot;使用 GDB 调试内核&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>qemu-system-x86_64 ... -s -S        # gdb stub, frozen at reset</span></span>
<span class="line"><span>gdb build/opencube_base.elf          # the pre-strip ELF has symbols</span></span>
<span class="line"><span>(gdb) target remote localhost:1234</span></span>
<span class="line"><span>(gdb) break kmain</span></span>
<span class="line"><span>(gdb) continue</span></span></code></pre></div><p><code>make kernel</code> 命令特意保留了 <code>build/opencube_base.elf</code> 文件，就是为了这个目的 - 最终的 <code>build/opencube.elf</code> 文件已被剥离调试符号。</p><h2 id="确定性回放" tabindex="-1">确定性回放 <a class="header-anchor" href="#确定性回放" aria-label="Permalink to &quot;确定性回放&quot;">​</a></h2><p>构建是可复现的 - 相同的源代码树会产生字节完全相同的 ELF 文件，因此一个可以复现两次的崩溃，两次产生的字节也是相同的。在网络测试中，可以结合 QEMU 自身的 <code>-icount</code> 参数来获得时间稳定性。</p><h2 id="一目了然的设备矩阵" tabindex="-1">一目了然的设备矩阵 <a class="header-anchor" href="#一目了然的设备矩阵" aria-label="Permalink to &quot;一目了然的设备矩阵&quot;">​</a></h2><p>点亮各个驱动家族所需的 QEMU 参数在<a href="./../drivers/storage.html">驱动手册</a>中已制表呈现 - 请精确附加你要调试的设备。</p>`,13)])])}const b=a(o,[["render",i]]);export{u as __pageData,b as default};
